import math

import networkx as nx

from .baselines import EnvyCycleElimination


class ApproximateEFkX:
    """
    Algorithm 3: ApproximateEFkX

    å¯¹äº k >= 2ï¼Œç›®æ ‡æ˜¯è®¡ç®—ä¸€ä¸ªå®Œæ•´çš„ï¼š

        (k + 1) / (k + 2)-EFkX allocation

    æ€»æµç¨‹ï¼š
        1. åˆ›å»º seed allocation X0
        2. ä½¿ç”¨ G3PA å¾—åˆ° partial allocation X1
        3. ä½¿ç”¨ AllocateAndEliminateCritical å¾—åˆ° partial allocation X2
        4. ä½¿ç”¨ Envy Cycle Elimination åˆ†é…å‰©ä½™ goods
    """

    def __init__(self, k=2):
        if k < 2:
            raise ValueError(
                "Algorithm 3 requires k >= 2."
            )

        self.k = k

        # å®éªŒå¹³å°ä½¿ç”¨è¿™ä¸ªå±æ€§è‡ªåŠ¨å†³å®š MaxAlphaEFkX çš„ k
        self.eval_k = k

        self.alpha = (k + 1) / (k + 2)

        self.name = f"Approximate-EF{k}X"



    def run(self, instance):
        """
        Algorithm 3 çš„æ€»å…¥å£ã€‚

        è¾“å…¥ï¼š
            instance:
                instance.n
                instance.m
                instance.valuations

        è¾“å‡ºï¼š
            å®Œæ•´ allocationï¼Œæ ¼å¼ï¼š
                {
                    0: [goods...],
                    1: [goods...],
                    ...
                }
        """
        self._validate_instance(instance)

        # -------------------------------------------------
        # Phase 0: åˆ›å»ºåˆå§‹ seed allocation X0
        # -------------------------------------------------
        allocation, remaining_items = self._create_seed_allocation(instance)

        # å¦‚æœåˆå§‹åŒ–åå·²ç»æ²¡æœ‰å‰©ä½™ goodsï¼Œç›´æ¥è¿”å›
        if not remaining_items:
            return allocation

        # -------------------------------------------------
        # Phase 1: G3PA
        #
        # è¾“å…¥ seed allocation X0
        # è¾“å‡ºæ»¡è¶³ Properties (a)-(f) çš„ partial allocation X1
        # -------------------------------------------------
        allocation, remaining_items = self._g3pa(
            instance=instance,
            allocation=allocation,
            remaining_items=remaining_items
        )

        g3pa_properties = self._check_g3pa_properties(
            instance, allocation, remaining_items
        )
        if not all(g3pa_properties[key] for key in "abcdef"):
            raise AssertionError(
                "G3PA output violates Properties (a)-(f): "
                f"{g3pa_properties['violations']}"
            )

        # G3PA æœ‰å¯èƒ½å·²ç»äº§ç”Ÿå®Œæ•´ allocation
        if not remaining_items:
            return allocation

        # -------------------------------------------------
        # Phase 2: AllocateAndEliminateCritical
        #
        # æ¶ˆé™¤ pool ä¸­æ‰€æœ‰ 1/(k+1)-critical goods
        # -------------------------------------------------
        allocation, remaining_items = (
            self._allocate_and_eliminate_critical(
                instance=instance,
                allocation=allocation,
                remaining_items=remaining_items
            )
        )

        remaining_critical = self._find_agents_with_critical_goods(
            valuations=instance.valuations,
            allocation=allocation,
            remaining_items=remaining_items,
        )
        if remaining_critical:
            raise AssertionError(
                "AllocateAndEliminateCritical left inclusive "
                f"1/(k+1)-critical goods in the pool: {remaining_critical}"
            )

        # Critical goods å¤„ç†è¿‡ç¨‹ä¸­ä¹Ÿå¯èƒ½åˆ†å®Œæ‰€æœ‰ goods
        if not remaining_items:
            return allocation

        # -------------------------------------------------
        # Phase 3: Envy Cycle Elimination
        #
        # å°† pool ä¸­å‰©ä½™ goods å…¨éƒ¨åˆ†é…
        # -------------------------------------------------
        ece = EnvyCycleElimination()

        final_allocation = ece.run_from_partial(
            instance=instance,
            allocation=allocation,
            remaining_items=remaining_items
        )

        return final_allocation

    def _validate_instance(self, instance):
        """
        æ£€æŸ¥è¾“å…¥æ˜¯å¦æ»¡è¶³å½“å‰å®ç°æ‰€éœ€è¦çš„åŸºæœ¬æ¡ä»¶ã€‚
        """
        if instance.n <= 0:
            raise ValueError("The number of agents must be positive.")

        if instance.m < instance.n:
            raise ValueError(
                "Algorithm 3 requires a seed allocation with one good "
                "per agent, so the current implementation requires m >= n."
            )

        if instance.valuations.shape != (instance.n, instance.m):
            raise ValueError(
                "The valuation matrix shape must be (n, m)."
            )

        if (instance.valuations < 0).any():
            raise ValueError(
                "Algorithm 3 assumes non-negative additive valuations."
            )

    def _create_seed_allocation(self, instance):
        """
        åˆ›å»º seed allocation X0ã€‚

        å½“å‰ä½¿ç”¨ä¸€è½® Round-Robinï¼š
            æ¯ä¸ª agent æŒ‰ç…§ 0,1,...,n-1 çš„é¡ºåºï¼Œ
            ä»å‰©ä½™ goods ä¸­é€‰æ‹©è‡ªå·±ä»·å€¼æœ€é«˜çš„ goodã€‚

        æœ€ç»ˆï¼š
            æ¯ä¸ª agent æ°å¥½æ‹¥æœ‰ä¸€ä¸ª goodï¼›
            å…¶ä½™ goods ç•™åœ¨ pool ä¸­ã€‚

        è¿”å›ï¼š
            allocation
            remaining_items
        """
        n = instance.n
        m = instance.m
        valuations = instance.valuations

        allocation = {i: [] for i in range(n)}
        remaining_items = list(range(m))

        for agent in range(n):
            best_item = max(
                remaining_items,
                key=lambda good: valuations[agent][good]
            )

            allocation[agent].append(best_item)
            remaining_items.remove(best_item)

        return allocation, remaining_items

    def _bundle_value(self, valuations, agent, bundle):
        """è®¡ç®— agent å¯¹ bundle çš„ additive valueã€‚"""
        return sum(valuations[agent][good] for good in bundle)

    @staticmethod
    def _strict_scaled_compare(
            left_value,
            left_multiplier,
            right_value,
            right_multiplier,
            rel_tol=1e-12,
            abs_tol=1e-12
    ):
        """Compare scaled values without turning a numerical tie into ``>``.

        Returns 1, 0, or -1.  Integer multipliers are used for every rational
        threshold in G3PA, so alpha=(k+1)/(k+2) and its reciprocal are never
        rounded before comparison.  ``isclose`` only classifies numerically
        indistinguishable non-integral inputs as tied; ties are never strict.
        """
        left = float(left_multiplier) * float(left_value)
        right = float(right_multiplier) * float(right_value)
        if math.isclose(left, right, rel_tol=rel_tol, abs_tol=abs_tol):
            return 0
        return 1 if left > right else -1

    def _proxy_value(self, valuations, agent, bundle):
        value = self._bundle_value(valuations, agent, bundle)
        if len(bundle) == 1:
            return float(value)
        return float(value) / self.alpha

    def _is_critical_good(
            self,
            valuations,
            allocation,
            agent,
            good,
            beta=None,
            tolerance=1e-12
    ):
        """
        åˆ¤æ–­ good æ˜¯å¦æ˜¯ agent çš„ beta-critical goodï¼š

            v_i(g) >= beta * v_i(X_i)
        """
        if beta is None:
            beta = 1 / (self.k + 1)

        own_value = self._bundle_value(
            valuations,
            agent,
            allocation[agent]
        )

        good_value = valuations[agent][good]

        # Definition 2.2 is inclusive.  Do not use an additive tolerance,
        # which could incorrectly classify a value below the boundary.
        if beta == 1 / (self.k + 1):
            return self._strict_scaled_compare(
                good_value, self.k + 1, own_value, 1
            ) >= 0
        comparison = self._strict_scaled_compare(
            good_value, 1, own_value, beta
        )
        return comparison >= 0

    def _is_strict_critical_good(
            self, valuations, allocation, agent, good
    ):
        """The strict boundary used by G3PA Property (f) and Lemma 3.5."""
        own_value = self._bundle_value(
            valuations, agent, allocation[agent]
        )
        return self._strict_scaled_compare(
            valuations[agent][good], self.k + 1, own_value, 1
        ) > 0

    def _check_g3pa_properties(
            self,
            instance,
            allocation,
            remaining_items,
            allow_full_exception=True
    ):
        """Independently check G3PA output Properties (a)-(f).

        The returned dictionary contains one boolean per property plus detailed
        violations.  Property (f) deliberately uses *strict* critical goods;
        an equality at v_i(g)=v_i(X_i)/(k+1) is tracked by the inclusive
        critical-good helper used by Algorithm 5, but is not strict-critical.
        """
        valuations = instance.valuations
        violations = {key: [] for key in "abcdef"}
        full_exception = allow_full_exception and not remaining_items

        for agent in range(instance.n):
            own_bundle = allocation[agent]
            own_value = self._bundle_value(valuations, agent, own_bundle)
            if not full_exception and len(own_bundle) not in (1, self.k + 1):
                violations["a"].append((agent, list(own_bundle)))

            for other in range(instance.n):
                if other == agent:
                    continue
                other_values = sorted(
                    float(valuations[agent][good])
                    for good in allocation[other]
                )
                residual = (
                    sum(other_values[self.k:])
                    if len(other_values) >= self.k else 0.0
                )
                if len(own_bundle) == 1 and self._strict_scaled_compare(
                        residual, 1, own_value, 1
                ) > 0:
                    violations["b"].append((agent, other, own_value, residual))
                if self._strict_scaled_compare(
                        residual, self.k + 1,
                        own_value, self.k + 2
                ) > 0:
                    violations["c"].append((agent, other, own_value, residual))

            for good in remaining_items:
                good_value = float(valuations[agent][good])
                if self._strict_scaled_compare(good_value, 1, own_value, 1) > 0:
                    violations["d"].append((agent, good, own_value, good_value))
                if len(own_bundle) == self.k + 1 and self._strict_scaled_compare(
                        good_value, self.k + 1, own_value, 1
                ) > 0:
                    violations["e"].append((agent, good, own_value, good_value))

            if len(own_bundle) == 1:
                strict_critical = [
                    good for good in remaining_items
                    if self._is_strict_critical_good(
                        valuations, allocation, agent, good
                    )
                ]
                critical_value = self._bundle_value(
                    valuations, agent, strict_critical
                )
                if len(strict_critical) > self.k or self._strict_scaled_compare(
                        critical_value, self.k + 2,
                        own_value, self.k + 1
                ) > 0:
                    violations["f"].append(
                        (agent, strict_critical, own_value, critical_value)
                    )

        return {
            **{key: not value for key, value in violations.items()},
            "violations": violations,
        }

    def _get_critical_goods(
            self,
            valuations,
            allocation,
            remaining_items,
            agent,
            beta=None
    ):
        """è¿”å› pool ä¸­æ‰€æœ‰å¯¹ agent æ˜¯ beta-critical çš„ goodsã€‚"""
        if beta is None:
            beta = 1 / (self.k + 1)

        return [
            good
            for good in remaining_items
            if self._is_critical_good(
                valuations=valuations,
                allocation=allocation,
                agent=agent,
                good=good,
                beta=beta
            )
        ]

    def _find_agents_with_critical_goods(
            self,
            valuations,
            allocation,
            remaining_items,
            beta=None
    ):
        """
        è¿”å›æ‰€æœ‰å­˜åœ¨ critical goods çš„ agentsï¼Œä»¥åŠå¯¹åº” goodsã€‚
        """
        if beta is None:
            beta = 1 / (self.k + 1)

        result = {}

        for agent in allocation:
            critical_goods = self._get_critical_goods(
                valuations=valuations,
                allocation=allocation,
                remaining_items=remaining_items,
                agent=agent,
                beta=beta
            )

            if critical_goods:
                result[agent] = critical_goods

        return result

    def _has_critical_goods(
            self,
            valuations,
            allocation,
            remaining_items,
            beta=None
    ):
        """åˆ¤æ–­ pool ä¸­æ˜¯å¦è¿˜å­˜åœ¨ critical goodsã€‚"""
        if not remaining_items:
            return False

        return bool(
            self._find_agents_with_critical_goods(
                valuations=valuations,
                allocation=allocation,
                remaining_items=remaining_items,
                beta=beta
            )
        )

